// Validate the language and set a per-scene word budget that keeps the finished
// video under 60s (so it still counts as a YouTube Short).
//
// Only languages that put SPACES between words belong here: a downstream karaoke /
// caption step splits text on whitespace, so Chinese/Japanese/Thai would break.
const LANGUAGES = {
  'English (US)':        'English',
  'Vietnamese':          'Vietnamese',
  'Spanish':             'Spanish',
  'French':              'French',
  'German':              'German',
  'Portuguese (Brazil)': 'Brazilian Portuguese',
  'Indonesian':          'Indonesian',
};

const picked = $json['Language'];
const languageName = LANGUAGES[picked];
if (!languageName) {
  throw new Error(`Unsupported language: "${picked}". Add it to the LANGUAGES map in this node.`);
}

// Word budget = what keeps the script short enough for a <60s Short.
// A typical TTS voice speaks ~2.32 words/sec including pauses; aim at ~55s => ~128 words
// for the WHOLE video, split across the scenes as a hard per-scene cap handed to the LLM.
// Raise TOTAL_WORDS if you don't care about the 60s Shorts limit (~2.32 words = 1 second).
const TOTAL_WORDS = 125;
const scenes = Number($json['Number of Scenes']) || 5;
const wordsPerScene = Math.max(8, Math.floor(TOTAL_WORDS / scenes));

return { json: { ...$json, languageName, wordsPerScene } };

const raw = $input.first().json;
let content;
if (raw.candidates) {                                // Gemini
  content = raw.candidates[0] && raw.candidates[0].content && raw.candidates[0].content.parts && raw.candidates[0].content.parts[0] && raw.candidates[0].content.parts[0].text;
} else if (Array.isArray(raw.content)) {             // Claude
  const textBlock = raw.content.find((b) => b.type === 'text');
  content = textBlock && textBlock.text;
} else if (raw.choices) {                            // OpenAI-style, if you swap the model
  content = raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content;
}
if (!content) {
  throw new Error('The LLM returned no content. Check that the API key on the model node is valid and still has quota.');
}
content = content.trim();
if (content.startsWith('```')) {
  content = content.replace(/^```[a-zA-Z]*\n/, '').replace(/```$/, '').trim();
}
let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error('Could not parse the LLM reply as JSON: ' + e.message + ' -- raw: ' + content.slice(0, 300));
}
const scenes = parsed.scenes || parsed.Scenes || [];
if (!Array.isArray(scenes) || scenes.length === 0) {
  throw new Error('The LLM reply contained no valid scenes array. Check the prompt and the raw model output.');
}
return [{ json: { scenes } }];
